import{_ as o,C as n,o as r,c as i,a5 as t,E as s}from"./chunks/framework.BwlBv862.js";const g=JSON.parse('{"title":"Diagnostiquer une opération échouée","description":"","frontmatter":{"title":"Diagnostiquer une opération échouée","docId":"user.preferences.troubleshooting","translationKey":"user.preferences.troubleshooting","locale":"fr","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"40d8c5706363baa28e4114397696c8c2adb320843271a00efb3772be0322d5e2","translationRevision":"c9765cbd7e1784cbe7de04640e0de66ab0ed723aaf8933226353489559379fd2","order":30},"headers":[],"relativePath":"fr/user/preferences/troubleshooting.md","filePath":"fr/user/preferences/troubleshooting.md","lastUpdated":1794611623000}'),l={name:"fr/user/preferences/troubleshooting.md"};function u(c,e,d,p,m,f){const a=n("DemoFrame");return r(),i("div",null,[e[0]||(e[0]=t('<h1 id="diagnose-a-failed-operation" tabindex="-1">Diagnostiquer une opération échouée <a class="header-anchor" href="#diagnose-a-failed-operation" aria-label="Permalink to &quot;Diagnostiquer une opération échouée {#diagnose-a-failed-operation}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objectif et prérequis <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objectif et prérequis {#goal-and-prerequisites}&quot;">​</a></h2><p>Identifier le composant en échec et recueillir un rapport utile sans déclencher des effets à répétition. Il faut la version de l’application, l’heure approximative de l’échec et l’opération tentée. Gardez une <a href="./backups.html">sauvegarde</a> avant toute réinitialisation ou remplacement de données.</p><h2 id="inspect-the-nearest-evidence" tabindex="-1">Examiner les éléments les plus proches <a class="header-anchor" href="#inspect-the-nearest-evidence" aria-label="Permalink to &quot;Examiner les éléments les plus proches {#inspect-the-nearest-evidence}&quot;">​</a></h2><ol><li>Lisez l’erreur affichée à l’endroit de l’échec. Utilisez son action d’état diagnostique ou ouvrez <strong>Diagnostics</strong> pour consulter les entrées associées.</li><li>Filtrez par source, niveau ou texte. Les sources utiles incluent LIVE, surveillance, plugins, compte, synchronisation, mises à jour, transport, catalogue, installation et collaboration.</li><li>Sélectionnez l’entrée concernée et conservez son heure, son code, les identifiants de requête/entité et une courte description. Développez les détails lorsqu’ils sont disponibles.</li><li>Copiez les diagnostics filtrés ou exportez le rapport texte. Si le presse-papiers ou l’exportation échoue, utilisez le texte de repli affiché. Examinez-le avant partage ; retirez les jetons privés, cookies, liens d’invitation et contenus personnels.</li><li>Incluez une courte reproduction : page, créateur/profil/plugin sélectionné, action effectuée, résultat attendu et résultat réel. Précisez si cela s’est produit avant ou après une mise à jour.</li></ol><h2 id="isolate-common-failures" tabindex="-1">Isoler les échecs courants <a class="header-anchor" href="#isolate-common-failures" aria-label="Permalink to &quot;Isoler les échecs courants {#isolate-common-failures}&quot;">​</a></h2><p>Pour un flux vide, effacez la recherche et les filtres, reprenez le défilement et confirmez la <a href="./../live/connections.html">connexion</a>. Un défilement en pause n’est pas une déconnexion. Un indicateur de perte d’affichage ne prouve pas que les points ou statistiques ont perdu le même événement.</p><p>Pour une automatisation sans exécution, vérifiez le profil actif, l’activation de l’événement/action, le déclencheur, les chemins des champs de filtre et le délai. Examinez l’historique avant de modifier les effets. <strong>Test</strong> peut exécuter des actions audio, HTTP, points et plugins.</p><p>Pour un échec de plugin, lisez l’erreur de tâche d’installation ou de connexion. Pour Cloud, vérifiez l’état du compte et le domaine concerné plutôt que de remplacer un cookie TikTok. Pour les incrustations, examinez l’état de la passerelle et la configuration de source. Pour les mises à jour, utilisez les <a href="./../updates.html">conseils de mise à jour manuelle</a> lorsque l’installation est indisponible.</p><h2 id="expected-result-and-status" tabindex="-1">Résultat attendu et état <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Résultat attendu et état {#expected-result-and-status}&quot;">​</a></h2><p>Le filtrage, la copie et l’exportation texte des diagnostics sont disponibles. Une application empaquetée a aussi besoin de ses ressources web et de l’environnement d’exécution de la plateforme. Sous Linux, vérifiez l’environnement GTK/WebKitGTK pris en charge et la session X11/XWayland ; sous Windows, vérifiez WebView2. Consultez les <a href="./../requirements.html">prérequis</a> pour le périmètre d’installation.</p><h2 id="recovery" tabindex="-1">Récupération <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Récupération {#recovery}&quot;">​</a></h2><p>Réessayez après correction de la cause précise. Pour les conflits de révision, rechargez et examinez l’état actuellement enregistré. Pour une commande distante non confirmée, consultez son journal/état avant d’en envoyer une autre : un délai d’attente dépassé peut suivre un effet réussi. Si le démarrage échoue, signalez le paquet, la version et le journal de démarrage plutôt que de supprimer le répertoire de données.</p>',13)),s(a,{scenario:"diagnostics",locale:"fr",tour:"diagnostics",title:"Démo : diagnostics"}),e[1]||(e[1]=t('<h2 id="operational-details" tabindex="-1">Détails de fonctionnement <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Détails de fonctionnement {#operational-details}&quot;">​</a></h2><p>Diagnostics est un journal UI en mémoire, limité à 2 000 entrées ou 2 MiB. Les répétitions en cinq secondes sont regroupées. La vue montre d’abord 100 entrées ; l’export contient toutes les entrées filtrées, mais <strong>Effacer</strong> supprime le journal entier. Exportez avant de fermer, redémarrer, effacer, changer de compte Cloud connu ou vous déconnecter : ces changements vident cet historique.</p><p>Sans fenêtre, cherchez le journal natif <code>tiktools.log</code> (<code>controller.log</code> en mode contrôleur) dans <code>%LOCALAPPDATA%/TikTools/logs</code> sous Windows ou <code>${XDG_DATA_HOME:-~/.local/share}/TikTools/logs</code> sous Linux. <code>TIKTOOLS_HOME</code> change la racine et <code>TIKTOOLS_LOG_DIR</code> remplace le répertoire des journaux. Si leur initialisation échoue, aucun fichier n’est garanti ; conservez l’erreur du terminal/démarrage disponible. La rédaction UI n’est pas garantie pour les journaux natifs : relisez avant partage.</p>',3))])}const v=o(l,[["render",u]]);export{g as __pageData,v as default};
